    territory_map = observation.get('territory_map', [])

    # Current position
    x, y = position

    # Initialize move to stay still
    dx, dy = 0, 0

    # Helper functions
    def in_bounds(px, py):
        return 0 <= px < grid_width and 0 <= py < grid_height

    def adjacent_positions(px, py):
        for nx, ny in [(px+1, py), (px-1, py), (px, py+1), (px, py-1)]:
            if in_bounds(nx, ny):
                yield (nx, ny)

    # Resource collection logic
    if resources:
