    # Territory control: move towards own territory if not already there
    if territory_map:
        # Assume territory_map is a 2D list, with some indicator of own territory, e.g., value == 1
        own_territory_value = 1
        def get_territory(px, py):
            if in_bounds(px, py):
                return territory_map[py][px]
            return None
        if get_territory(x, y) != own_territory_value:
            # Search neighboring tiles for own territory
            for nx, ny in adjacent_positions(x, y):
                if get_territory(nx, ny) == own_territory_value:
                    dx = nx - x
                    dy = ny - y
                    # limit to -1, 0, 1
                    dx = max(-1, min(1, dx))
                    dy = max(-1, min(1, dy))
                    return [dx, dy]
            # Else, move in direction towards majority of own territory
            # For simplicity, move randomly
            # But to be deterministic, pick a direction towards the closest own territory cell
            # Find all own territory cells
            own_cells = []
            for py in range(grid_height):
                for px in range(grid_width):
                    if get_territory(px, py) == own_territory_value:
